/opt/homebrew/bin/python3 - <<'EOF'
import json
p="/Users/kristinarash/SecondBrain/Inbox/meetings/.graphify_chunks/out/out_04.json"
d=json.load(open(p))
ids={n["id"] for n in d["nodes"]}
print("nodes",len(d["nodes"]),"unique",len(ids))
print("edges",len(d["edges"]))
bad=[(e["source"],e["target"]) for e in d["edges"] if e["source"] not in ids or e["target"] not in ids]
print("dangling",bad)
he=[n for h in d["hyperedges"] for n in h["nodes"] if n not in ids]
print("hyper dangling",he)
# confidence checks
rels={"references","conceptually_related_to","shares_data_with","semantically_similar_to","rationale_for","implements","cites"}
print("bad rel",{e["relation"] for e in d["edges"]}-rels)
for e in d["edges"]:
    c,s=e["confidence"],e["confidence_score"]
    if c=="EXTRACTED" and s!=1.0: print("BAD EXTR",e)
    if c=="INFERRED" and not (0.4<=s<=0.9): print("BAD INF",e)
    if c=="AMBIGUOUS" and not (0.1<=s<=0.3): print("BAD AMB",e)
    if "confidence_score" not in e: print("MISSING",e)
# dup nodes
from collections import Counter
print([k for k,v in Counter(n["id"] for n in d["nodes"]).items() if v>1])
# files coverage
import os
files={n["source_file"] for n in d["nodes"]}|{e["source_file"] for e in d["edges"]}
listed=[l.strip() for l in open("/Users/kristinarash/SecondBrain/Inbox/meetings/.graphify_chunks/chunk_04.txt") if l.strip()]
base={os.path.basename(l) for l in listed}
print("missing files:",sorted(base-files))
EOF
